int minCostClimbingStairs(vector<int> &cost) {
    int n = cost.size();

    if (n==1) return cost[0];

    int prev2 = cost[0];
    int prev1 = cost[1];

    for (int i=2; i<n; i++) {
        int curr = cost[i] + 
        min(prev1, prev2);

        prev2 = prev1;
        prev1 = curr;
    }

    // Return minimum of cost to 
    // climb (n-1)th stair and 
    // cost to reach (n-2)th stair
    return min(prev1, prev2);
}

